import logging
import traceback
import sys
import six

from socket import timeout as socket_timeout

from taf.transport.ssh.connection import connect
from taf.transport.ssh.exceptions import ConnectionError
from ute_common_util.timeout import Timeout

logger = logging.getLogger(__name__)

SSHClientException = ConnectionError


class SSHConnectionManager(object):
    """Class responsible for ssh connection management."""

    BANNER_ERR_MSG = 'Error reading SSH protocol banner'
    LOCALHOST = '127.0.0.1'

    def __init__(self, host, user, password, port, timeout, prompt, remote_host, retry_timeout=60, fallback_prompt=None,
                 private_key=None, root_username=None, root_password=None, root_private_key=None, remote_ssh_user='ute',
                 remote_ssh_pass='ute', remote_ssh_prompt='$ ', remote_ssh_port=22, **_):
        self.user = user
        self.password = '' if private_key else password
        self.host = host
        self.port = port
        self.timeout = timeout
        self.prompt = prompt
        self.retry_timeout = retry_timeout
        self.private_key = private_key
        self.service_tunnel = None
        self.remote_ssh_user = remote_ssh_user
        self.remote_ssh_pass = remote_ssh_pass
        self.remote_ssh_prompt = remote_ssh_prompt
        self.remote_ssh_port = remote_ssh_port
        self.root_username = root_username
        self.root_password = root_password
        self.root_private_key = root_private_key
        self.root_credentials = True if root_private_key else False
        self.remote_host = remote_host
        self.forwarder = True if remote_host else False
        self.fallback_prompt = fallback_prompt
        self.ssh_connection = None

    @property
    def client(self):
        """ Connection Manager Client (e.g. ssh, telnet). """

        return self.ssh_connection

    def start(self, timeout=None):
        """ Starts connection manager. """
        timeout = timeout if timeout else self.retry_timeout
        exception_msg = ''
        time = Timeout(timeout)
        while time.is_not_reached():
            try:
                return self._login()
            except (SSHClientException, socket_timeout) as e:
                e_type, e_value, e_traceback = sys.exc_info() if six.PY3 else (None, None, None)
                exception_msg = str(e)
                if self._check_retry_condition(exception_msg):
                    Timeout(1).sleep_until_reached()
                    continue
                self.stop()
                break
        logger.debug(
            "".join(traceback.format_exception(e_type, e_value, e_traceback, limit=2))) if six.PY3 else logger.debug(
            traceback.format_exc())
        raise SSHClientException(exception_msg)

    def _check_retry_condition(self, exception_msg):
        conditions = (SSHConnectionManager.BANNER_ERR_MSG, "timed out", "No existing session")
        for condition in conditions:
            if condition in exception_msg:
                return True
        return False

    def _login(self):
        if self.forwarder:
            ssh_connection_proxy = connect(hostname=self.remote_host, username=self.remote_ssh_user,
                                           password=self.remote_ssh_pass, port=self.remote_ssh_port,
                                           timeout=self.timeout)
            self.ssh_connection = connect(hostname=self.host, username=self.user, password=self.password,
                                          proxy=ssh_connection_proxy, port=self.port, timeout=self.timeout)
        if self.root_credentials:
            self.ssh_connection = connect(hostname=SSHConnectionManager.LOCALHOST, username=self.root_username,
                                          password=self.root_password, port=self.port,
                                          key_path=self.root_private_key,
                                          timeout=self.timeout)
        else:
            self.ssh_connection = connect(hostname=self.host, username=self.user, password=self.password,
                                          port=self.port, key_path=self.private_key,
                                          timeout=self.timeout)
        return self.client

    def stop(self):
        """Stops and cleans connection. """
        self._clean_ssh()

    def _clean_ssh(self):
        if self.ssh_connection:
            self.ssh_connection.disconnect()
            self.ssh_connection = None

    def _extract_remote_ssh_credentials(self, kwargs):
        return (kwargs.get('remote_ssh_user', 'ute'),
                kwargs.get('remote_ssh_pass', 'ute'),
                kwargs.get('remote_ssh_prompt', '$ '),
                kwargs.get('remote_ssh_port', 22))

    def _extract_root_credentials(self, kwargs):
        if kwargs.get('root_private_key'):
            return {'username': kwargs.get('root_username', 'toor4nsn'),
                    'password': kwargs.get('root_password', ''),
                    'keyfile': kwargs.get('root_private_key')}
        return None
